-- c015-v005-chirho.sql
-- JOHN c15-v5 - IND
-- Akulah adalah – pokok–anggur kamu – ranting–ranting –yang tinggal di–dalam Aku dan–Aku di–dalam dia ini menghasilkan buah banyak karena tanpa Aku tidak kamu–dapat melakukan apa–apa
BEGIN;
-- 4301500501: ἐγώ (G1473) → "Akulah" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'ind'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '4301500501' AND p.language_id = (SELECT id FROM language WHERE code = 'ind') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '4301500501' FROM np ON CONFLICT DO NOTHING;
